	('af0ace58-10fe-46af-baa6-53c307b693ad', 'phnom-penh-wat-phnom', '201d6e00-d0d5-47e4-8633-4b31bd5a88c7', 'attraction', 'temple', 'Wat Phnom', 'The hilltop temple said to have given the city its name, set in a small park.', 11.5761, 104.9235, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/Wat_Phnom_Doun_Penh.jpg/960px-Wat_Phnom_Doun_Penh.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Photo: Wikipedia/Wikimedia Commons (licence on file page) - https://en.wikipedia.org/wiki/Wat_Phnom', 1.00, 45, 420, 1080, false, 'Prices and opening hours are indicative; confirm locally before visiting.', '{temple,temples,culture,photography}', true, false, NULL, '2026-10-22 12:28:56.104551+00', '2026-10-22 12:28:56.104551+00'),
	('e48c799f-7216-4060-b825-5ae59173bb1d', 'phnom-penh-royal-palace', '201d6e00-d0d5-47e4-8633-4b31bd5a88c7', 'attraction', 'landmark', 'Royal Palace', 'The residence of the King of Cambodia, with the Throne Hall and the Silver Pagoda inside the walled compound.', 11.5636, 104.9312, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Le_Palais_Royal_%28Phnom_Penh%29_%286997773481%29.jpg/960px-Le_Palais_Royal_%28Phnom_Penh%29_%286997773481%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Photo: Wikipedia/Wikimedia Commons (licence on file page) - https://en.wikipedia.org/wiki/Royal_Palace_of_Cambodia', 10.00, 90, 480, 1020, false, 'Prices and opening hours are indicative; confirm locally before visiting.', '{landmark,photography,culture,relaxed}', true, false, NULL, '2026-10-22 12:28:56.104551+00', '2026-10-22 12:28:56.104551+00'),
	('dacfdb5a-791e-48af-ac1c-744d14b9a21a', 'phnom-penh-national-museum-of-cambodia', '201d6e00-d0d5-47e4-8633-4b31bd5a88c7', 'attraction', 'museum', 'National Museum of Cambodia', 'Houses the country''s largest collection of Khmer art, set in a red-roofed pavilion building with a calm courtyard garden.', 11.5649, 104.9298, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/Entrance_of_the_National_Museum_of_Cambodia.jpg/960px-Entrance_of_the_National_Museum_of_Cambodia.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Photo: Wikipedia/Wikimedia Commons (licence on file page) - https://en.wikipedia.org/wiki/National_Museum_of_Cambodia', 10.00, 90, 480, 1020, false, 'Prices and opening hours are indicative; confirm locally before visiting.', '{museum,culture,history}', true, false, NULL, '2026-10-22 12:28:56.104551+00', '2026-10-22 12:28:56.104551+00'),
	('f73c35e5-20e0-4375-a984-4810ba6f15e5', 'phnom-penh-tuol-sleng-genocide-museum', '201d6e00-d0d5-47e4-8633-4b31bd5a88c7', 'attraction', 'museum', 'Tuol Sleng Genocide Museum', 'A former school used as a prison during the Khmer Rouge era; a sombre but important memorial. Not suitable for young children.', 11.5493, 104.9174, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Tuol_Sleng.jpg/960px-Tuol_Sleng.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Photo: Wikipedia/Wikimedia Commons (licence on file page) - https://en.wikipedia.org/wiki/Tuol_Sleng_Genocide_Museum', 10.00, 120, 480, 1020, false, 'Prices and opening hours are indicative; confirm locally before visiting.', '{museum,culture,history}', false, false, NULL, '2026-10-22 12:28:56.104551+00', '2026-10-22 12:28:56.104551+00'),
