	('76369184-a1ba-49f9-984e-fcbd33f58fdf', '9b17a1d8-7ee6-4b69-a051-e23b726716bd', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/%EC%A4%91%ED%99%94%EC%A0%84%EC%9D%98_%EB%82%AE.jpg/960px-%EC%A4%91%ED%99%94%EC%A0%84%EC%9D%98_%EB%82%AE.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Seoul', 'Photo: Wikipedia/Wikimedia Commons (licence on file page) - https://en.wikipedia.org/wiki/Seoul', 0),
	('c406d526-793b-4bf0-aafd-fd13a20e5954', '9b17a1d8-7ee6-4b69-a051-e23b726716bd', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Gyedong-gil_street_with_climbing_plants_at_golden_hour_in_Seoul_South_Korea.jpg/960px-Gyedong-gil_street_with_climbing_plants_at_golden_hour_in_Seoul_South_Korea.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Gyedong-gil street with climbing plants at golden hour in Seoul South Korea', 'Photo: Basile Morin, CC BY-SA 4.0 via Wikimedia Commons - https://commons.wikimedia.org/wiki/File%3AGyedong-gil_street_with_climbing_plants_at_golden_hour_in_Seoul_South_Korea.jpg', 1),
	('fe1af45f-8ace-4890-a44e-e0a57e61e0ca', '9b17a1d8-7ee6-4b69-a051-e23b726716bd', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Interior_view_of_the_main_hall_of_Bongeunsa_temple_in_Seoul_South_Korea.jpg/960px-Interior_view_of_the_main_hall_of_Bongeunsa_temple_in_Seoul_South_Korea.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Interior view of the main hall of Bongeunsa temple in Seoul South Korea', 'Photo: Basile Morin, CC BY-SA 4.0 via Wikimedia Commons - https://commons.wikimedia.org/wiki/File%3AInterior_view_of_the_main_hall_of_Bongeunsa_temple_in_Seoul_South_Korea.jpg', 2),
	('aaa3659e-872b-4a9c-8276-0fa86a0956b2', '9b17a1d8-7ee6-4b69-a051-e23b726716bd', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Skyline_view_from_Seoul_City_%28South_Korea%29.jpg/960px-Skyline_view_from_Seoul_City_%28South_Korea%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Skyline view from Seoul City (South Korea)', 'Photo: Flickr - Laurie Nevay
